"""Declarative base and the ORM models (tables live in infra; domain stays I/O-free)."""

from datetime import datetime
from typing import TypedDict

from sqlalchemy import JSON, CheckConstraint, DateTime, Integer, MetaData, String
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

# Deterministic constraint names: Postgres would otherwise invent them, and
# autogenerated migrations could not reliably drop or alter those constraints.
NAMING_CONVENTION: dict[str, str] = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)


class ModelFilesJson(TypedDict):
    name: str
    source: str
    revision: str
    files: dict[str, str]


class Bm25ParamsJson(TypedDict):
    k: float
    b: float
    avg_len: float
    avg_len_auto: bool


class BuildWarningJson(TypedDict):
    kind: str
    collection: str
    error_type: str


# A failed build names its exception type; a succeeded one has none (IndexBuild).
# The allowed status values are the status check's job, so each check tests one rule.
_ERROR_TYPE_MATCHES_STATUS = "(status = 'failed') = (error_type IS NOT NULL)"


class IndexBuildRow(Base):
    """One index build (ADR 0006): what produced a Qdrant collection, and whether it went live.

    JSON columns use SQLAlchemy's generic JSON type, so unit tests run the same model on
    SQLite. The names and total chunk count are also plain columns, for simple queries.
    """

    __tablename__ = "index_builds"
    __table_args__ = (
        CheckConstraint("status IN ('succeeded', 'failed')", name="status"),
        CheckConstraint("chunk_count >= 0", name="chunk_count_non_negative"),
        CheckConstraint(_ERROR_TYPE_MATCHES_STATUS, name="error_type_status"),
    )

    build_id: Mapped[str] = mapped_column(String(32), primary_key=True)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    status: Mapped[str] = mapped_column(String(16))
    collection: Mapped[str] = mapped_column(String(255), unique=True)
    document_hashes: Mapped[dict[str, str]] = mapped_column(JSON)
    chunking_version: Mapped[str] = mapped_column(String(32))
    dense_model: Mapped[str] = mapped_column(String(255))
    sparse_model: Mapped[str] = mapped_column(String(255))
    models: Mapped[dict[str, ModelFilesJson]] = mapped_column(JSON)  # "dense" and "sparse"
    chunk_count: Mapped[int] = mapped_column(Integer)
    chunk_counts: Mapped[dict[str, int]] = mapped_column(JSON)
    drop_stats: Mapped[dict[str, dict[str, int]]] = mapped_column(JSON)
    warnings: Mapped[list[BuildWarningJson]] = mapped_column(JSON)
    error_type: Mapped[str | None] = mapped_column(String(255))  # type name only, never a message
    # NULL (not JSON null) before migration 0004: fastembed's BM25 defaults (ADR 0009).
    sparse_params: Mapped[Bm25ParamsJson | None] = mapped_column(JSON(none_as_null=True))
